    {"name": "Team Impact Report (OPQ)", "url": "https://www.shl.com/solutions/products/team-impact/", "test_type": "P", "description": "OPQ-derived team report mapping personality to Belbin-style team roles. Used for team building, onboarding and development interventions.", "job_levels": ["professional", "managerial"], "competencies": ["team dynamics", "team roles", "collaboration", "team building"]},
